window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-61aba51b948a5bba"]={"versions": [{"id": "FIG-61aba51b948a5bba", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-VFB-Architektur- und Allokationsdiagramm (Konzeptuelle Abbildung von VFB-Systemebene auf die konkrete ECU-Deployment-Ebene).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform R4.0.3, Spezifikation <code>AUTOSAR_EXP_VFB</code> (Kapitel 7: <em>Mode Management</em>).</li>\n<li><strong>Technischer Zweck:</strong> Darstellung des architektonischen Entwurfsmusters für verteilte Modusanforderungen (<em>Distributed Mode Management Pattern</em>). Das Schaubild visualisiert, wie eine fahrzeugweite Modusanforderung (hier Klemmenstatus wie Kl. 15 / Kl. 30 durch <code>VehicleClampControl</code>) netzwerkweit an die Basissoftware-Modus-Manager (<code>BswM</code>) mehrerer verteilter Steuergeräte (<code>ECU1</code>, <code>ECU2</code>) und die dortigen Anwendungs-Softwarekomponenten (<code>App1</code>, <code>App2</code>) propagiert wird.</li>\n<li><strong>Kernmotivation:</strong> Da AUTOSAR-Modus-Switch-Schnittstellen (<code>ModeSwitchInterface</code>) normativ strikt ECU-lokal gebunden sind, löst dieses Muster die Entkopplung fahrzeugweiter Modusentscheidungen von der lokalen ECU-Modus-Arbitrierung mittels Proxy-Komponenten (<code>VehicleClampProxy</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### VFB-Ebene (Abstrakte Sicht, obere Bildhälfte)</p>\n<ul class=\"fig-list\">\n<li><strong><code>VCC: VehicleClampControl</code>:</strong> Applikations-SW-C (<code>ApplicationSwComponentType</code>), instanziiert als Singleton (gekennzeichnet durch das Einzelsymbol oben rechts). Zentraler Master für die Klemmensteuerung.</li>\n<li><strong><code>VCP: VehicleClampProxy</code>:</strong> Proxy-SW-C (<code>ApplicationSwComponentType</code> oder <code>ComplexDeviceDriver</code>), gekennzeichnet als mehrfach instanziierbar (überlappendes Quadratsymbol oben rechts).</li>\n<li><strong><code>App1: Application1</code> & <code>App2: Application2</code>:</strong> Funktions-SW-Cs, die vom resultierenden Modus abhängig sind.</li>\n<li><strong>VFB (Virtual Function Bus):</strong> Abstrakter Kommunikationskanal (orangefarbener Layer), der die physikalische Topologie verbirgt.</li>\n</ul>\n<p class=\"fig-p\">#### ECU-Deployment-Ebene (Konkrete Allokation, untere Bildhälfte)</p>\n<ul class=\"fig-list\">\n<li><strong>ECU1:</strong></li>\n<li>Beherbergt <code>VCC</code> (Master), eine lokale Instanz von <code>VCP</code> sowie <code>App1</code>.</li>\n<li>Schichten: <code>RTE1</code> (Runtime Environment) und <code>BSW1</code> (Basissoftware) mit <code>BswM Service</code>.</li>\n<li><strong>ECU2:</strong></li>\n<li>Beherbergt eine separate Instanz von <code>VCP</code> sowie <code>App2</code>.</li>\n<li>Schichten: <code>RTE2</code> und <code>BSW2</code> mit lokalem <code>BswM Service</code>.</li>\n<li><strong><code>BswM Service</code> (<code>BswM</code>):</strong> AUTOSAR Basic Software Mode Manager (Service-Komponente in der BSW), zuständig für die lokale Regelauswertung und Modus-Arbitrierung.</li>\n</ul>\n<p class=\"fig-p\">#### Ports & Schnittstellen-Klassifikation</p>\n<ul class=\"fig-list\">\n<li><strong><code>VCC</code> (P-Port) $\\rightarrow$ <code>VCP</code> (R-Port):</strong></li>\n<li><strong>Darstellung:</strong> Weißes Quadrat mit Pfeil nach unten (P-Port / Provided) auf weißes Quadrat mit Pfeil nach oben (R-Port / Required).</li>\n<li><strong>Schnittstellentyp:</strong> <code>SenderReceiverInterface</code>. 1:n-Verbindung zur fahrzeugweiten Signalübertragung (intra-ECU auf ECU1 und inter-ECU über Fahrzeugbus an ECU2).</li>\n<li><strong><code>VCP</code> (P-Port) $\\rightarrow$ <code>BswM Service</code> (R-Port):</strong></li>\n<li><strong>Darstellung:</strong> Schwarzes Quadrat mit weißem Dreieck nach unten.</li>\n<li><strong>Schnittstellentyp:</strong> <code>SenderReceiverInterface</code> (Mode Request Port, MRP) bzw. standardisierte Mode-Request-Schnittstelle. Übergibt die angeforderte Klemme als Modus-Anforderung an den BswM.</li>\n<li><strong><code>BswM Service</code> (P-Port) $\\rightarrow$ <code>App1</code> / <code>App2</code> (R-Port):</strong></li>\n<li><strong>Darstellung:</strong> Schwarzes Quadrat mit drei Punkten (Mode Declaration Group / Mode Switch Port).</li>\n<li><strong>Schnittstellentyp:</strong> <code>ModeSwitchInterface</code>. Der BswM agiert als Modus-Manager (<code>PPortPrototype</code>), die Applikationen als Modus-Nutzer (<code>RPortPrototype</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Modus-Triggerung (VCC):</strong> Die zentrale Instanz <code>VCC</code> auf ECU1 bestimmt anhand von Eingangsgrößen (z. B. Zündschloss, Start-Stopp-Signal) einen Zustandswechsel der Fahrzeugklemme (z. B. Übergang von <em>Clamp_Standby</em> nach <em>Clamp_15</em>).</li>\n<li><strong>Signal-Distribution (Sender/Receiver):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>VCC</code> schreibt den Status via <code>Rte_Write</code> an seinen P-Port.</li>\n<li><strong>Intra-ECU (ECU1):</strong> <code>RTE1</code> leitet das Datum direkt an den R-Port der lokalen <code>VCP</code>-Instanz weiter.</li>\n<li><strong>Inter-ECU (ECU2):</strong> <code>RTE1</code> übergibt das Signal an den COM-Stack (<code>Com</code> / <code>PduR</code> / Bus-Interface) von <code>BSW1</code>. Das Signal wird in eine Netzwerk-I-PDU gemappt, über den Fahrzeugbus (CAN/LIN/FlexRay) übertragen, in <code>BSW2</code> empfangen und via <code>RTE2</code> an die <code>VCP</code>-Instanz auf ECU2 zugestellt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Lokale Modus-Anforderung (VCP $\\rightarrow$ BswM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Auf beiden ECUs empfängt <code>VCP</code> das Datum und sendet eine lokale Modusanforderung an den <code>BswM Service</code> (z. B. Aufruf von <code>Rte_Write</code> auf einem BswM-Mode-Request-Port).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>BswM-Regelauswertung & Arbitrierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>BswM</code> jeder ECU wertet seine konfigurierten <code>BswMRules</code> (Expressions mit logischen Operatoren) autonom aus. Er prüft, ob die Klemmenanforderung mit dem aktuellen lokalen ECU-Zustand (z. B. Spannungslevel, Diagnose-Zustand, Fehlerstatus) kompatibel ist.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modus-Umschaltung (Mode Switch):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach erfolgreicher Arbitrierung führt der BswM eine <code>BswMActionList</code> aus.</li>\n<li>Der BswM ruft die RTE-Funktion <code>Rte_Switch_&lt;p&gt;_&lt;modeGroup&gt;()</code> auf.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Notifizierung der Applikationen (App1, App2):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die jeweilige RTE (<code>RTE1</code>, <code>RTE2</code>) setzt den Modus der Modus-Gruppe aktiv und feuert konfigurierte <code>ModeSwitchEvents</code> (<code>ON_ENTRY</code>, <code>ON_EXIT</code>, <code>ON_TRANSITION</code>).</li>\n<li>Die entsprechenden Runnables von <code>App1</code> (ECU1) und <code>App2</code> (ECU2) werden gestartet, gestoppt oder in ihrer Ausführung getaktet.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Strikte Lokalität von <code>ModeSwitchInterface</code>:</strong></li>\n<li>Gemäß AUTOSAR VFB- und RTE-Spezifikation ist ein <code>ModeSwitchInterface</code> rein ECU-lokal. Es existiert kein Com-Mapping für Mode-Switches über Netzwerk-PDUs. Ein direkter Anschluss eines <code>ModeSwitchInterface</code> über ECU-Grenzen hinweg ist ungültig und schlägt bei der RTE-Generierung fehl.</li>\n<li>Das Proxy-Muster (<code>VehicleClampProxy</code>) ist das normative Entwurfsmuster, um Modus-Anforderungen netzwerkweit zu transportieren.</li>\n<li><strong>RTE-API-Vertrag:</strong></li>\n<li><code>VCC</code> $\\rightarrow$ <code>VCP</code>: Asynchrones oder unblocking Sender/Receiver-API (<code>Rte_Write_&lt;p&gt;_&lt;o&gt;()</code> / <code>Rte_Read_&lt;p&gt;_&lt;o&gt;()</code>).</li>\n<li><code>VCP</code> $\\rightarrow$ <code>BswM</code>: Zugriff auf den BswM-Mode-Request-Port via RTE-Write oder standardisierte BswM-Service-APIs.</li>\n<li><code>BswM</code> $\\rightarrow$ <code>App</code>: BswM nutzt <code>Rte_Switch()</code>. Applikationen greifen über <code>Rte_Mode()</code> ab oder reagieren event-gesteuert auf <code>ModeSwitchEvent</code>.</li>\n<li><strong>BswM-Konfigurationsanforderungen:</strong></li>\n<li>Jedes Steuergerät benötigt im BswM-Modell einen <code>BswMModeRequestPort</code> vom Typ <code>BswMSwComponentType</code>, der auf den Zielport des <code>VCP</code> verweist.</li>\n<li>In der BswM-Konfiguration muss ein <code>BswMActionListItem</code> mit einer <code>BswMAction</code> vom Typ <code>BswMModeSwitch</code> definiert sein, um den RTE-Modus-Switch zu initiieren.</li>\n<li><strong>Timing & Latenzen:</strong></li>\n<li>Die Klemmenreaktion erfolgt asynchron zwischen den ECUs: ECU2 reagiert aufgrund von Bus-Übertragungs- und Debounce-Zeiten verzögert gegenüber ECU1.</li>\n<li>Timeout- und Ausfallüberwachung (z. B. Verlust der Klemmen-PDU via Com-Deadline-Monitoring) muss im BswM von ECU2 konfiguriert werden, um ein sicheres Rückfallverhalten (<em>Safe State</em>) zu gewährleisten.</li>\n</ul>"}, {"id": "FIG-b057440554f96dee", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-VFB-Architektur- und Allokationsdiagramm (Konzeptuelle Abbildung von VFB-Systemebene auf die konkrete ECU-Deployment-Ebene).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform R4.0.3, Spezifikation <code>AUTOSAR_EXP_VFB</code> (Kapitel 7: <em>Mode Management</em>).</li>\n<li><strong>Technischer Zweck:</strong> Darstellung des architektonischen Entwurfsmusters für verteilte Modusanforderungen (<em>Distributed Mode Management Pattern</em>). Das Schaubild visualisiert, wie eine fahrzeugweite Modusanforderung (hier Klemmenstatus wie Kl. 15 / Kl. 30 durch <code>VehicleClampControl</code>) netzwerkweit an die Basissoftware-Modus-Manager (<code>BswM</code>) mehrerer verteilter Steuergeräte (<code>ECU1</code>, <code>ECU2</code>) und die dortigen Anwendungs-Softwarekomponenten (<code>App1</code>, <code>App2</code>) propagiert wird.</li>\n<li><strong>Kernmotivation:</strong> Da AUTOSAR-Modus-Switch-Schnittstellen (<code>ModeSwitchInterface</code>) normativ strikt ECU-lokal gebunden sind, löst dieses Muster die Entkopplung fahrzeugweiter Modusentscheidungen von der lokalen ECU-Modus-Arbitrierung mittels Proxy-Komponenten (<code>VehicleClampProxy</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### VFB-Ebene (Abstrakte Sicht, obere Bildhälfte)</p>\n<ul class=\"fig-list\">\n<li><strong><code>VCC: VehicleClampControl</code>:</strong> Applikations-SW-C (<code>ApplicationSwComponentType</code>), instanziiert als Singleton (gekennzeichnet durch das Einzelsymbol oben rechts). Zentraler Master für die Klemmensteuerung.</li>\n<li><strong><code>VCP: VehicleClampProxy</code>:</strong> Proxy-SW-C (<code>ApplicationSwComponentType</code> oder <code>ComplexDeviceDriver</code>), gekennzeichnet als mehrfach instanziierbar (überlappendes Quadratsymbol oben rechts).</li>\n<li><strong><code>App1: Application1</code> & <code>App2: Application2</code>:</strong> Funktions-SW-Cs, die vom resultierenden Modus abhängig sind.</li>\n<li><strong>VFB (Virtual Function Bus):</strong> Abstrakter Kommunikationskanal (orangefarbener Layer), der die physikalische Topologie verbirgt.</li>\n</ul>\n<p class=\"fig-p\">#### ECU-Deployment-Ebene (Konkrete Allokation, untere Bildhälfte)</p>\n<ul class=\"fig-list\">\n<li><strong>ECU1:</strong></li>\n<li>Beherbergt <code>VCC</code> (Master), eine lokale Instanz von <code>VCP</code> sowie <code>App1</code>.</li>\n<li>Schichten: <code>RTE1</code> (Runtime Environment) und <code>BSW1</code> (Basissoftware) mit <code>BswM Service</code>.</li>\n<li><strong>ECU2:</strong></li>\n<li>Beherbergt eine separate Instanz von <code>VCP</code> sowie <code>App2</code>.</li>\n<li>Schichten: <code>RTE2</code> und <code>BSW2</code> mit lokalem <code>BswM Service</code>.</li>\n<li><strong><code>BswM Service</code> (<code>BswM</code>):</strong> AUTOSAR Basic Software Mode Manager (Service-Komponente in der BSW), zuständig für die lokale Regelauswertung und Modus-Arbitrierung.</li>\n</ul>\n<p class=\"fig-p\">#### Ports & Schnittstellen-Klassifikation</p>\n<ul class=\"fig-list\">\n<li><strong><code>VCC</code> (P-Port) $\\rightarrow$ <code>VCP</code> (R-Port):</strong></li>\n<li><strong>Darstellung:</strong> Weißes Quadrat mit Pfeil nach unten (P-Port / Provided) auf weißes Quadrat mit Pfeil nach oben (R-Port / Required).</li>\n<li><strong>Schnittstellentyp:</strong> <code>SenderReceiverInterface</code>. 1:n-Verbindung zur fahrzeugweiten Signalübertragung (intra-ECU auf ECU1 und inter-ECU über Fahrzeugbus an ECU2).</li>\n<li><strong><code>VCP</code> (P-Port) $\\rightarrow$ <code>BswM Service</code> (R-Port):</strong></li>\n<li><strong>Darstellung:</strong> Schwarzes Quadrat mit weißem Dreieck nach unten.</li>\n<li><strong>Schnittstellentyp:</strong> <code>SenderReceiverInterface</code> (Mode Request Port, MRP) bzw. standardisierte Mode-Request-Schnittstelle. Übergibt die angeforderte Klemme als Modus-Anforderung an den BswM.</li>\n<li><strong><code>BswM Service</code> (P-Port) $\\rightarrow$ <code>App1</code> / <code>App2</code> (R-Port):</strong></li>\n<li><strong>Darstellung:</strong> Schwarzes Quadrat mit drei Punkten (Mode Declaration Group / Mode Switch Port).</li>\n<li><strong>Schnittstellentyp:</strong> <code>ModeSwitchInterface</code>. Der BswM agiert als Modus-Manager (<code>PPortPrototype</code>), die Applikationen als Modus-Nutzer (<code>RPortPrototype</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Modus-Triggerung (VCC):</strong> Die zentrale Instanz <code>VCC</code> auf ECU1 bestimmt anhand von Eingangsgrößen (z. B. Zündschloss, Start-Stopp-Signal) einen Zustandswechsel der Fahrzeugklemme (z. B. Übergang von <em>Clamp_Standby</em> nach <em>Clamp_15</em>).</li>\n<li><strong>Signal-Distribution (Sender/Receiver):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>VCC</code> schreibt den Status via <code>Rte_Write</code> an seinen P-Port.</li>\n<li><strong>Intra-ECU (ECU1):</strong> <code>RTE1</code> leitet das Datum direkt an den R-Port der lokalen <code>VCP</code>-Instanz weiter.</li>\n<li><strong>Inter-ECU (ECU2):</strong> <code>RTE1</code> übergibt das Signal an den COM-Stack (<code>Com</code> / <code>PduR</code> / Bus-Interface) von <code>BSW1</code>. Das Signal wird in eine Netzwerk-I-PDU gemappt, über den Fahrzeugbus (CAN/LIN/FlexRay) übertragen, in <code>BSW2</code> empfangen und via <code>RTE2</code> an die <code>VCP</code>-Instanz auf ECU2 zugestellt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Lokale Modus-Anforderung (VCP $\\rightarrow$ BswM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Auf beiden ECUs empfängt <code>VCP</code> das Datum und sendet eine lokale Modusanforderung an den <code>BswM Service</code> (z. B. Aufruf von <code>Rte_Write</code> auf einem BswM-Mode-Request-Port).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>BswM-Regelauswertung & Arbitrierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>BswM</code> jeder ECU wertet seine konfigurierten <code>BswMRules</code> (Expressions mit logischen Operatoren) autonom aus. Er prüft, ob die Klemmenanforderung mit dem aktuellen lokalen ECU-Zustand (z. B. Spannungslevel, Diagnose-Zustand, Fehlerstatus) kompatibel ist.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modus-Umschaltung (Mode Switch):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach erfolgreicher Arbitrierung führt der BswM eine <code>BswMActionList</code> aus.</li>\n<li>Der BswM ruft die RTE-Funktion <code>Rte_Switch_&lt;p&gt;_&lt;modeGroup&gt;()</code> auf.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Notifizierung der Applikationen (App1, App2):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die jeweilige RTE (<code>RTE1</code>, <code>RTE2</code>) setzt den Modus der Modus-Gruppe aktiv und feuert konfigurierte <code>ModeSwitchEvents</code> (<code>ON_ENTRY</code>, <code>ON_EXIT</code>, <code>ON_TRANSITION</code>).</li>\n<li>Die entsprechenden Runnables von <code>App1</code> (ECU1) und <code>App2</code> (ECU2) werden gestartet, gestoppt oder in ihrer Ausführung getaktet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Strikte Lokalität von <code>ModeSwitchInterface</code>:</strong></li>\n<li>Gemäß AUTOSAR VFB- und RTE-Spezifikation ist ein <code>ModeSwitchInterface</code> rein ECU-lokal. Es existiert kein Com-Mapping für Mode-Switches über Netzwerk-PDUs. Ein direkter Anschluss eines <code>ModeSwitchInterface</code> über ECU-Grenzen hinweg ist ungültig und schlägt bei der RTE-Generierung fehl.</li>\n<li>Das Proxy-Muster (<code>VehicleClampProxy</code>) ist das normative Entwurfsmuster, um Modus-Anforderungen netzwerkweit zu transportieren.</li>\n<li><strong>RTE-API-Vertrag:</strong></li>\n<li><code>VCC</code> $\\rightarrow$ <code>VCP</code>: Asynchrones oder unblocking Sender/Receiver-API (<code>Rte_Write_&lt;p&gt;_&lt;o&gt;()</code> / <code>Rte_Read_&lt;p&gt;_&lt;o&gt;()</code>).</li>\n<li><code>VCP</code> $\\rightarrow$ <code>BswM</code>: Zugriff auf den BswM-Mode-Request-Port via RTE-Write oder standardisierte BswM-Service-APIs.</li>\n<li><code>BswM</code> $\\rightarrow$ <code>App</code>: BswM nutzt <code>Rte_Switch()</code>. Applikationen greifen über <code>Rte_Mode()</code> ab oder reagieren event-gesteuert auf <code>ModeSwitchEvent</code>.</li>\n<li><strong>BswM-Konfigurationsanforderungen:</strong></li>\n<li>Jedes Steuergerät benötigt im BswM-Modell einen <code>BswMModeRequestPort</code> vom Typ <code>BswMSwComponentType</code>, der auf den Zielport des <code>VCP</code> verweist.</li>\n<li>In der BswM-Konfiguration muss ein <code>BswMActionListItem</code> mit einer <code>BswMAction</code> vom Typ <code>BswMModeSwitch</code> definiert sein, um den RTE-Modus-Switch zu initiieren.</li>\n<li><strong>Timing & Latenzen:</strong></li>\n<li>Die Klemmenreaktion erfolgt asynchron zwischen den ECUs: ECU2 reagiert aufgrund von Bus-Übertragungs- und Debounce-Zeiten verzögert gegenüber ECU1.</li>\n<li>Timeout- und Ausfallüberwachung (z. B. Verlust der Klemmen-PDU via Com-Deadline-Monitoring) muss im BswM von ECU2 konfiguriert werden, um ein sicheres Rückfallverhalten (<em>Safe State</em>) zu gewährleisten.</li>\n</ul>"}, {"id": "FIG-3d60268f1dd13148", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-VFB-Architektur- und Allokationsdiagramm (Konzeptuelle Abbildung von VFB-Systemebene auf die konkrete ECU-Deployment-Ebene).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform R4.0.3, Spezifikation <code>AUTOSAR_EXP_VFB</code> (Kapitel 7: <em>Mode Management</em>).</li>\n<li><strong>Technischer Zweck:</strong> Darstellung des architektonischen Entwurfsmusters für verteilte Modusanforderungen (<em>Distributed Mode Management Pattern</em>). Das Schaubild visualisiert, wie eine fahrzeugweite Modusanforderung (hier Klemmenstatus wie Kl. 15 / Kl. 30 durch <code>VehicleClampControl</code>) netzwerkweit an die Basissoftware-Modus-Manager (<code>BswM</code>) mehrerer verteilter Steuergeräte (<code>ECU1</code>, <code>ECU2</code>) und die dortigen Anwendungs-Softwarekomponenten (<code>App1</code>, <code>App2</code>) propagiert wird.</li>\n<li><strong>Kernmotivation:</strong> Da AUTOSAR-Modus-Switch-Schnittstellen (<code>ModeSwitchInterface</code>) normativ strikt ECU-lokal gebunden sind, löst dieses Muster die Entkopplung fahrzeugweiter Modusentscheidungen von der lokalen ECU-Modus-Arbitrierung mittels Proxy-Komponenten (<code>VehicleClampProxy</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### VFB-Ebene (Abstrakte Sicht, obere Bildhälfte)</p>\n<ul class=\"fig-list\">\n<li><strong><code>VCC: VehicleClampControl</code>:</strong> Applikations-SW-C (<code>ApplicationSwComponentType</code>), instanziiert als Singleton (gekennzeichnet durch das Einzelsymbol oben rechts). Zentraler Master für die Klemmensteuerung.</li>\n<li><strong><code>VCP: VehicleClampProxy</code>:</strong> Proxy-SW-C (<code>ApplicationSwComponentType</code> oder <code>ComplexDeviceDriver</code>), gekennzeichnet als mehrfach instanziierbar (überlappendes Quadratsymbol oben rechts).</li>\n<li><strong><code>App1: Application1</code> & <code>App2: Application2</code>:</strong> Funktions-SW-Cs, die vom resultierenden Modus abhängig sind.</li>\n<li><strong>VFB (Virtual Function Bus):</strong> Abstrakter Kommunikationskanal (orangefarbener Layer), der die physikalische Topologie verbirgt.</li>\n</ul>\n<p class=\"fig-p\">#### ECU-Deployment-Ebene (Konkrete Allokation, untere Bildhälfte)</p>\n<ul class=\"fig-list\">\n<li><strong>ECU1:</strong></li>\n<li>Beherbergt <code>VCC</code> (Master), eine lokale Instanz von <code>VCP</code> sowie <code>App1</code>.</li>\n<li>Schichten: <code>RTE1</code> (Runtime Environment) und <code>BSW1</code> (Basissoftware) mit <code>BswM Service</code>.</li>\n<li><strong>ECU2:</strong></li>\n<li>Beherbergt eine separate Instanz von <code>VCP</code> sowie <code>App2</code>.</li>\n<li>Schichten: <code>RTE2</code> und <code>BSW2</code> mit lokalem <code>BswM Service</code>.</li>\n<li><strong><code>BswM Service</code> (<code>BswM</code>):</strong> AUTOSAR Basic Software Mode Manager (Service-Komponente in der BSW), zuständig für die lokale Regelauswertung und Modus-Arbitrierung.</li>\n</ul>\n<p class=\"fig-p\">#### Ports & Schnittstellen-Klassifikation</p>\n<ul class=\"fig-list\">\n<li><strong><code>VCC</code> (P-Port) $\\rightarrow$ <code>VCP</code> (R-Port):</strong></li>\n<li><strong>Darstellung:</strong> Weißes Quadrat mit Pfeil nach unten (P-Port / Provided) auf weißes Quadrat mit Pfeil nach oben (R-Port / Required).</li>\n<li><strong>Schnittstellentyp:</strong> <code>SenderReceiverInterface</code>. 1:n-Verbindung zur fahrzeugweiten Signalübertragung (intra-ECU auf ECU1 und inter-ECU über Fahrzeugbus an ECU2).</li>\n<li><strong><code>VCP</code> (P-Port) $\\rightarrow$ <code>BswM Service</code> (R-Port):</strong></li>\n<li><strong>Darstellung:</strong> Schwarzes Quadrat mit weißem Dreieck nach unten.</li>\n<li><strong>Schnittstellentyp:</strong> <code>SenderReceiverInterface</code> (Mode Request Port, MRP) bzw. standardisierte Mode-Request-Schnittstelle. Übergibt die angeforderte Klemme als Modus-Anforderung an den BswM.</li>\n<li><strong><code>BswM Service</code> (P-Port) $\\rightarrow$ <code>App1</code> / <code>App2</code> (R-Port):</strong></li>\n<li><strong>Darstellung:</strong> Schwarzes Quadrat mit drei Punkten (Mode Declaration Group / Mode Switch Port).</li>\n<li><strong>Schnittstellentyp:</strong> <code>ModeSwitchInterface</code>. Der BswM agiert als Modus-Manager (<code>PPortPrototype</code>), die Applikationen als Modus-Nutzer (<code>RPortPrototype</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Modus-Triggerung (VCC):</strong> Die zentrale Instanz <code>VCC</code> auf ECU1 bestimmt anhand von Eingangsgrößen (z. B. Zündschloss, Start-Stopp-Signal) einen Zustandswechsel der Fahrzeugklemme (z. B. Übergang von <em>Clamp_Standby</em> nach <em>Clamp_15</em>).</li>\n<li><strong>Signal-Distribution (Sender/Receiver):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>VCC</code> schreibt den Status via <code>Rte_Write</code> an seinen P-Port.</li>\n<li><strong>Intra-ECU (ECU1):</strong> <code>RTE1</code> leitet das Datum direkt an den R-Port der lokalen <code>VCP</code>-Instanz weiter.</li>\n<li><strong>Inter-ECU (ECU2):</strong> <code>RTE1</code> übergibt das Signal an den COM-Stack (<code>Com</code> / <code>PduR</code> / Bus-Interface) von <code>BSW1</code>. Das Signal wird in eine Netzwerk-I-PDU gemappt, über den Fahrzeugbus (CAN/LIN/FlexRay) übertragen, in <code>BSW2</code> empfangen und via <code>RTE2</code> an die <code>VCP</code>-Instanz auf ECU2 zugestellt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Lokale Modus-Anforderung (VCP $\\rightarrow$ BswM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Auf beiden ECUs empfängt <code>VCP</code> das Datum und sendet eine lokale Modusanforderung an den <code>BswM Service</code> (z. B. Aufruf von <code>Rte_Write</code> auf einem BswM-Mode-Request-Port).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>BswM-Regelauswertung & Arbitrierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>BswM</code> jeder ECU wertet seine konfigurierten <code>BswMRules</code> (Expressions mit logischen Operatoren) autonom aus. Er prüft, ob die Klemmenanforderung mit dem aktuellen lokalen ECU-Zustand (z. B. Spannungslevel, Diagnose-Zustand, Fehlerstatus) kompatibel ist.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modus-Umschaltung (Mode Switch):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach erfolgreicher Arbitrierung führt der BswM eine <code>BswMActionList</code> aus.</li>\n<li>Der BswM ruft die RTE-Funktion <code>Rte_Switch_&lt;p&gt;_&lt;modeGroup&gt;()</code> auf.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Notifizierung der Applikationen (App1, App2):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die jeweilige RTE (<code>RTE1</code>, <code>RTE2</code>) setzt den Modus der Modus-Gruppe aktiv und feuert konfigurierte <code>ModeSwitchEvents</code> (<code>ON_ENTRY</code>, <code>ON_EXIT</code>, <code>ON_TRANSITION</code>).</li>\n<li>Die entsprechenden Runnables von <code>App1</code> (ECU1) und <code>App2</code> (ECU2) werden gestartet, gestoppt oder in ihrer Ausführung getaktet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Strikte Lokalität von <code>ModeSwitchInterface</code>:</strong></li>\n<li>Gemäß AUTOSAR VFB- und RTE-Spezifikation ist ein <code>ModeSwitchInterface</code> rein ECU-lokal. Es existiert kein Com-Mapping für Mode-Switches über Netzwerk-PDUs. Ein direkter Anschluss eines <code>ModeSwitchInterface</code> über ECU-Grenzen hinweg ist ungültig und schlägt bei der RTE-Generierung fehl.</li>\n<li>Das Proxy-Muster (<code>VehicleClampProxy</code>) ist das normative Entwurfsmuster, um Modus-Anforderungen netzwerkweit zu transportieren.</li>\n<li><strong>RTE-API-Vertrag:</strong></li>\n<li><code>VCC</code> $\\rightarrow$ <code>VCP</code>: Asynchrones oder unblocking Sender/Receiver-API (<code>Rte_Write_&lt;p&gt;_&lt;o&gt;()</code> / <code>Rte_Read_&lt;p&gt;_&lt;o&gt;()</code>).</li>\n<li><code>VCP</code> $\\rightarrow$ <code>BswM</code>: Zugriff auf den BswM-Mode-Request-Port via RTE-Write oder standardisierte BswM-Service-APIs.</li>\n<li><code>BswM</code> $\\rightarrow$ <code>App</code>: BswM nutzt <code>Rte_Switch()</code>. Applikationen greifen über <code>Rte_Mode()</code> ab oder reagieren event-gesteuert auf <code>ModeSwitchEvent</code>.</li>\n<li><strong>BswM-Konfigurationsanforderungen:</strong></li>\n<li>Jedes Steuergerät benötigt im BswM-Modell einen <code>BswMModeRequestPort</code> vom Typ <code>BswMSwComponentType</code>, der auf den Zielport des <code>VCP</code> verweist.</li>\n<li>In der BswM-Konfiguration muss ein <code>BswMActionListItem</code> mit einer <code>BswMAction</code> vom Typ <code>BswMModeSwitch</code> definiert sein, um den RTE-Modus-Switch zu initiieren.</li>\n<li><strong>Timing & Latenzen:</strong></li>\n<li>Die Klemmenreaktion erfolgt asynchron zwischen den ECUs: ECU2 reagiert aufgrund von Bus-Übertragungs- und Debounce-Zeiten verzögert gegenüber ECU1.</li>\n<li>Timeout- und Ausfallüberwachung (z. B. Verlust der Klemmen-PDU via Com-Deadline-Monitoring) muss im BswM von ECU2 konfiguriert werden, um ein sicheres Rückfallverhalten (<em>Safe State</em>) zu gewährleisten.</li>\n</ul>"}, {"id": "FIG-b4d9427754c19270", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-VFB-Architektur- und Allokationsdiagramm (Konzeptuelle Abbildung von VFB-Systemebene auf die konkrete ECU-Deployment-Ebene).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform R4.0.3, Spezifikation <code>AUTOSAR_EXP_VFB</code> (Kapitel 7: <em>Mode Management</em>).</li>\n<li><strong>Technischer Zweck:</strong> Darstellung des architektonischen Entwurfsmusters für verteilte Modusanforderungen (<em>Distributed Mode Management Pattern</em>). Das Schaubild visualisiert, wie eine fahrzeugweite Modusanforderung (hier Klemmenstatus wie Kl. 15 / Kl. 30 durch <code>VehicleClampControl</code>) netzwerkweit an die Basissoftware-Modus-Manager (<code>BswM</code>) mehrerer verteilter Steuergeräte (<code>ECU1</code>, <code>ECU2</code>) und die dortigen Anwendungs-Softwarekomponenten (<code>App1</code>, <code>App2</code>) propagiert wird.</li>\n<li><strong>Kernmotivation:</strong> Da AUTOSAR-Modus-Switch-Schnittstellen (<code>ModeSwitchInterface</code>) normativ strikt ECU-lokal gebunden sind, löst dieses Muster die Entkopplung fahrzeugweiter Modusentscheidungen von der lokalen ECU-Modus-Arbitrierung mittels Proxy-Komponenten (<code>VehicleClampProxy</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### VFB-Ebene (Abstrakte Sicht, obere Bildhälfte)</p>\n<ul class=\"fig-list\">\n<li><strong><code>VCC: VehicleClampControl</code>:</strong> Applikations-SW-C (<code>ApplicationSwComponentType</code>), instanziiert als Singleton (gekennzeichnet durch das Einzelsymbol oben rechts). Zentraler Master für die Klemmensteuerung.</li>\n<li><strong><code>VCP: VehicleClampProxy</code>:</strong> Proxy-SW-C (<code>ApplicationSwComponentType</code> oder <code>ComplexDeviceDriver</code>), gekennzeichnet als mehrfach instanziierbar (überlappendes Quadratsymbol oben rechts).</li>\n<li><strong><code>App1: Application1</code> & <code>App2: Application2</code>:</strong> Funktions-SW-Cs, die vom resultierenden Modus abhängig sind.</li>\n<li><strong>VFB (Virtual Function Bus):</strong> Abstrakter Kommunikationskanal (orangefarbener Layer), der die physikalische Topologie verbirgt.</li>\n</ul>\n<p class=\"fig-p\">#### ECU-Deployment-Ebene (Konkrete Allokation, untere Bildhälfte)</p>\n<ul class=\"fig-list\">\n<li><strong>ECU1:</strong></li>\n<li>Beherbergt <code>VCC</code> (Master), eine lokale Instanz von <code>VCP</code> sowie <code>App1</code>.</li>\n<li>Schichten: <code>RTE1</code> (Runtime Environment) und <code>BSW1</code> (Basissoftware) mit <code>BswM Service</code>.</li>\n<li><strong>ECU2:</strong></li>\n<li>Beherbergt eine separate Instanz von <code>VCP</code> sowie <code>App2</code>.</li>\n<li>Schichten: <code>RTE2</code> und <code>BSW2</code> mit lokalem <code>BswM Service</code>.</li>\n<li><strong><code>BswM Service</code> (<code>BswM</code>):</strong> AUTOSAR Basic Software Mode Manager (Service-Komponente in der BSW), zuständig für die lokale Regelauswertung und Modus-Arbitrierung.</li>\n</ul>\n<p class=\"fig-p\">#### Ports & Schnittstellen-Klassifikation</p>\n<ul class=\"fig-list\">\n<li><strong><code>VCC</code> (P-Port) $\\rightarrow$ <code>VCP</code> (R-Port):</strong></li>\n<li><strong>Darstellung:</strong> Weißes Quadrat mit Pfeil nach unten (P-Port / Provided) auf weißes Quadrat mit Pfeil nach oben (R-Port / Required).</li>\n<li><strong>Schnittstellentyp:</strong> <code>SenderReceiverInterface</code>. 1:n-Verbindung zur fahrzeugweiten Signalübertragung (intra-ECU auf ECU1 und inter-ECU über Fahrzeugbus an ECU2).</li>\n<li><strong><code>VCP</code> (P-Port) $\\rightarrow$ <code>BswM Service</code> (R-Port):</strong></li>\n<li><strong>Darstellung:</strong> Schwarzes Quadrat mit weißem Dreieck nach unten.</li>\n<li><strong>Schnittstellentyp:</strong> <code>SenderReceiverInterface</code> (Mode Request Port, MRP) bzw. standardisierte Mode-Request-Schnittstelle. Übergibt die angeforderte Klemme als Modus-Anforderung an den BswM.</li>\n<li><strong><code>BswM Service</code> (P-Port) $\\rightarrow$ <code>App1</code> / <code>App2</code> (R-Port):</strong></li>\n<li><strong>Darstellung:</strong> Schwarzes Quadrat mit drei Punkten (Mode Declaration Group / Mode Switch Port).</li>\n<li><strong>Schnittstellentyp:</strong> <code>ModeSwitchInterface</code>. Der BswM agiert als Modus-Manager (<code>PPortPrototype</code>), die Applikationen als Modus-Nutzer (<code>RPortPrototype</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Modus-Triggerung (VCC):</strong> Die zentrale Instanz <code>VCC</code> auf ECU1 bestimmt anhand von Eingangsgrößen (z. B. Zündschloss, Start-Stopp-Signal) einen Zustandswechsel der Fahrzeugklemme (z. B. Übergang von <em>Clamp_Standby</em> nach <em>Clamp_15</em>).</li>\n<li><strong>Signal-Distribution (Sender/Receiver):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>VCC</code> schreibt den Status via <code>Rte_Write</code> an seinen P-Port.</li>\n<li><strong>Intra-ECU (ECU1):</strong> <code>RTE1</code> leitet das Datum direkt an den R-Port der lokalen <code>VCP</code>-Instanz weiter.</li>\n<li><strong>Inter-ECU (ECU2):</strong> <code>RTE1</code> übergibt das Signal an den COM-Stack (<code>Com</code> / <code>PduR</code> / Bus-Interface) von <code>BSW1</code>. Das Signal wird in eine Netzwerk-I-PDU gemappt, über den Fahrzeugbus (CAN/LIN/FlexRay) übertragen, in <code>BSW2</code> empfangen und via <code>RTE2</code> an die <code>VCP</code>-Instanz auf ECU2 zugestellt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Lokale Modus-Anforderung (VCP $\\rightarrow$ BswM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Auf beiden ECUs empfängt <code>VCP</code> das Datum und sendet eine lokale Modusanforderung an den <code>BswM Service</code> (z. B. Aufruf von <code>Rte_Write</code> auf einem BswM-Mode-Request-Port).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>BswM-Regelauswertung & Arbitrierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>BswM</code> jeder ECU wertet seine konfigurierten <code>BswMRules</code> (Expressions mit logischen Operatoren) autonom aus. Er prüft, ob die Klemmenanforderung mit dem aktuellen lokalen ECU-Zustand (z. B. Spannungslevel, Diagnose-Zustand, Fehlerstatus) kompatibel ist.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modus-Umschaltung (Mode Switch):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach erfolgreicher Arbitrierung führt der BswM eine <code>BswMActionList</code> aus.</li>\n<li>Der BswM ruft die RTE-Funktion <code>Rte_Switch_&lt;p&gt;_&lt;modeGroup&gt;()</code> auf.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Notifizierung der Applikationen (App1, App2):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die jeweilige RTE (<code>RTE1</code>, <code>RTE2</code>) setzt den Modus der Modus-Gruppe aktiv und feuert konfigurierte <code>ModeSwitchEvents</code> (<code>ON_ENTRY</code>, <code>ON_EXIT</code>, <code>ON_TRANSITION</code>).</li>\n<li>Die entsprechenden Runnables von <code>App1</code> (ECU1) und <code>App2</code> (ECU2) werden gestartet, gestoppt oder in ihrer Ausführung getaktet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Strikte Lokalität von <code>ModeSwitchInterface</code>:</strong></li>\n<li>Gemäß AUTOSAR VFB- und RTE-Spezifikation ist ein <code>ModeSwitchInterface</code> rein ECU-lokal. Es existiert kein Com-Mapping für Mode-Switches über Netzwerk-PDUs. Ein direkter Anschluss eines <code>ModeSwitchInterface</code> über ECU-Grenzen hinweg ist ungültig und schlägt bei der RTE-Generierung fehl.</li>\n<li>Das Proxy-Muster (<code>VehicleClampProxy</code>) ist das normative Entwurfsmuster, um Modus-Anforderungen netzwerkweit zu transportieren.</li>\n<li><strong>RTE-API-Vertrag:</strong></li>\n<li><code>VCC</code> $\\rightarrow$ <code>VCP</code>: Asynchrones oder unblocking Sender/Receiver-API (<code>Rte_Write_&lt;p&gt;_&lt;o&gt;()</code> / <code>Rte_Read_&lt;p&gt;_&lt;o&gt;()</code>).</li>\n<li><code>VCP</code> $\\rightarrow$ <code>BswM</code>: Zugriff auf den BswM-Mode-Request-Port via RTE-Write oder standardisierte BswM-Service-APIs.</li>\n<li><code>BswM</code> $\\rightarrow$ <code>App</code>: BswM nutzt <code>Rte_Switch()</code>. Applikationen greifen über <code>Rte_Mode()</code> ab oder reagieren event-gesteuert auf <code>ModeSwitchEvent</code>.</li>\n<li><strong>BswM-Konfigurationsanforderungen:</strong></li>\n<li>Jedes Steuergerät benötigt im BswM-Modell einen <code>BswMModeRequestPort</code> vom Typ <code>BswMSwComponentType</code>, der auf den Zielport des <code>VCP</code> verweist.</li>\n<li>In der BswM-Konfiguration muss ein <code>BswMActionListItem</code> mit einer <code>BswMAction</code> vom Typ <code>BswMModeSwitch</code> definiert sein, um den RTE-Modus-Switch zu initiieren.</li>\n<li><strong>Timing & Latenzen:</strong></li>\n<li>Die Klemmenreaktion erfolgt asynchron zwischen den ECUs: ECU2 reagiert aufgrund von Bus-Übertragungs- und Debounce-Zeiten verzögert gegenüber ECU1.</li>\n<li>Timeout- und Ausfallüberwachung (z. B. Verlust der Klemmen-PDU via Com-Deadline-Monitoring) muss im BswM von ECU2 konfiguriert werden, um ein sicheres Rückfallverhalten (<em>Safe State</em>) zu gewährleisten.</li>\n</ul>"}, {"id": "FIG-5c8ede4876b2a0a8", "releases": ["R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-VFB-Architektur- und Allokationsdiagramm (Konzeptuelle Abbildung von VFB-Systemebene auf die konkrete ECU-Deployment-Ebene).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform R4.0.3, Spezifikation <code>AUTOSAR_EXP_VFB</code> (Kapitel 7: <em>Mode Management</em>).</li>\n<li><strong>Technischer Zweck:</strong> Darstellung des architektonischen Entwurfsmusters für verteilte Modusanforderungen (<em>Distributed Mode Management Pattern</em>). Das Schaubild visualisiert, wie eine fahrzeugweite Modusanforderung (hier Klemmenstatus wie Kl. 15 / Kl. 30 durch <code>VehicleClampControl</code>) netzwerkweit an die Basissoftware-Modus-Manager (<code>BswM</code>) mehrerer verteilter Steuergeräte (<code>ECU1</code>, <code>ECU2</code>) und die dortigen Anwendungs-Softwarekomponenten (<code>App1</code>, <code>App2</code>) propagiert wird.</li>\n<li><strong>Kernmotivation:</strong> Da AUTOSAR-Modus-Switch-Schnittstellen (<code>ModeSwitchInterface</code>) normativ strikt ECU-lokal gebunden sind, löst dieses Muster die Entkopplung fahrzeugweiter Modusentscheidungen von der lokalen ECU-Modus-Arbitrierung mittels Proxy-Komponenten (<code>VehicleClampProxy</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### VFB-Ebene (Abstrakte Sicht, obere Bildhälfte)</p>\n<ul class=\"fig-list\">\n<li><strong><code>VCC: VehicleClampControl</code>:</strong> Applikations-SW-C (<code>ApplicationSwComponentType</code>), instanziiert als Singleton (gekennzeichnet durch das Einzelsymbol oben rechts). Zentraler Master für die Klemmensteuerung.</li>\n<li><strong><code>VCP: VehicleClampProxy</code>:</strong> Proxy-SW-C (<code>ApplicationSwComponentType</code> oder <code>ComplexDeviceDriver</code>), gekennzeichnet als mehrfach instanziierbar (überlappendes Quadratsymbol oben rechts).</li>\n<li><strong><code>App1: Application1</code> & <code>App2: Application2</code>:</strong> Funktions-SW-Cs, die vom resultierenden Modus abhängig sind.</li>\n<li><strong>VFB (Virtual Function Bus):</strong> Abstrakter Kommunikationskanal (orangefarbener Layer), der die physikalische Topologie verbirgt.</li>\n</ul>\n<p class=\"fig-p\">#### ECU-Deployment-Ebene (Konkrete Allokation, untere Bildhälfte)</p>\n<ul class=\"fig-list\">\n<li><strong>ECU1:</strong></li>\n<li>Beherbergt <code>VCC</code> (Master), eine lokale Instanz von <code>VCP</code> sowie <code>App1</code>.</li>\n<li>Schichten: <code>RTE1</code> (Runtime Environment) und <code>BSW1</code> (Basissoftware) mit <code>BswM Service</code>.</li>\n<li><strong>ECU2:</strong></li>\n<li>Beherbergt eine separate Instanz von <code>VCP</code> sowie <code>App2</code>.</li>\n<li>Schichten: <code>RTE2</code> und <code>BSW2</code> mit lokalem <code>BswM Service</code>.</li>\n<li><strong><code>BswM Service</code> (<code>BswM</code>):</strong> AUTOSAR Basic Software Mode Manager (Service-Komponente in der BSW), zuständig für die lokale Regelauswertung und Modus-Arbitrierung.</li>\n</ul>\n<p class=\"fig-p\">#### Ports & Schnittstellen-Klassifikation</p>\n<ul class=\"fig-list\">\n<li><strong><code>VCC</code> (P-Port) $\\rightarrow$ <code>VCP</code> (R-Port):</strong></li>\n<li><strong>Darstellung:</strong> Weißes Quadrat mit Pfeil nach unten (P-Port / Provided) auf weißes Quadrat mit Pfeil nach oben (R-Port / Required).</li>\n<li><strong>Schnittstellentyp:</strong> <code>SenderReceiverInterface</code>. 1:n-Verbindung zur fahrzeugweiten Signalübertragung (intra-ECU auf ECU1 und inter-ECU über Fahrzeugbus an ECU2).</li>\n<li><strong><code>VCP</code> (P-Port) $\\rightarrow$ <code>BswM Service</code> (R-Port):</strong></li>\n<li><strong>Darstellung:</strong> Schwarzes Quadrat mit weißem Dreieck nach unten.</li>\n<li><strong>Schnittstellentyp:</strong> <code>SenderReceiverInterface</code> (Mode Request Port, MRP) bzw. standardisierte Mode-Request-Schnittstelle. Übergibt die angeforderte Klemme als Modus-Anforderung an den BswM.</li>\n<li><strong><code>BswM Service</code> (P-Port) $\\rightarrow$ <code>App1</code> / <code>App2</code> (R-Port):</strong></li>\n<li><strong>Darstellung:</strong> Schwarzes Quadrat mit drei Punkten (Mode Declaration Group / Mode Switch Port).</li>\n<li><strong>Schnittstellentyp:</strong> <code>ModeSwitchInterface</code>. Der BswM agiert als Modus-Manager (<code>PPortPrototype</code>), die Applikationen als Modus-Nutzer (<code>RPortPrototype</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Modus-Triggerung (VCC):</strong> Die zentrale Instanz <code>VCC</code> auf ECU1 bestimmt anhand von Eingangsgrößen (z. B. Zündschloss, Start-Stopp-Signal) einen Zustandswechsel der Fahrzeugklemme (z. B. Übergang von <em>Clamp_Standby</em> nach <em>Clamp_15</em>).</li>\n<li><strong>Signal-Distribution (Sender/Receiver):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>VCC</code> schreibt den Status via <code>Rte_Write</code> an seinen P-Port.</li>\n<li><strong>Intra-ECU (ECU1):</strong> <code>RTE1</code> leitet das Datum direkt an den R-Port der lokalen <code>VCP</code>-Instanz weiter.</li>\n<li><strong>Inter-ECU (ECU2):</strong> <code>RTE1</code> übergibt das Signal an den COM-Stack (<code>Com</code> / <code>PduR</code> / Bus-Interface) von <code>BSW1</code>. Das Signal wird in eine Netzwerk-I-PDU gemappt, über den Fahrzeugbus (CAN/LIN/FlexRay) übertragen, in <code>BSW2</code> empfangen und via <code>RTE2</code> an die <code>VCP</code>-Instanz auf ECU2 zugestellt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Lokale Modus-Anforderung (VCP $\\rightarrow$ BswM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Auf beiden ECUs empfängt <code>VCP</code> das Datum und sendet eine lokale Modusanforderung an den <code>BswM Service</code> (z. B. Aufruf von <code>Rte_Write</code> auf einem BswM-Mode-Request-Port).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>BswM-Regelauswertung & Arbitrierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>BswM</code> jeder ECU wertet seine konfigurierten <code>BswMRules</code> (Expressions mit logischen Operatoren) autonom aus. Er prüft, ob die Klemmenanforderung mit dem aktuellen lokalen ECU-Zustand (z. B. Spannungslevel, Diagnose-Zustand, Fehlerstatus) kompatibel ist.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modus-Umschaltung (Mode Switch):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach erfolgreicher Arbitrierung führt der BswM eine <code>BswMActionList</code> aus.</li>\n<li>Der BswM ruft die RTE-Funktion <code>Rte_Switch_&lt;p&gt;_&lt;modeGroup&gt;()</code> auf.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Notifizierung der Applikationen (App1, App2):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die jeweilige RTE (<code>RTE1</code>, <code>RTE2</code>) setzt den Modus der Modus-Gruppe aktiv und feuert konfigurierte <code>ModeSwitchEvents</code> (<code>ON_ENTRY</code>, <code>ON_EXIT</code>, <code>ON_TRANSITION</code>).</li>\n<li>Die entsprechenden Runnables von <code>App1</code> (ECU1) und <code>App2</code> (ECU2) werden gestartet, gestoppt oder in ihrer Ausführung getaktet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Strikte Lokalität von <code>ModeSwitchInterface</code>:</strong></li>\n<li>Gemäß AUTOSAR VFB- und RTE-Spezifikation ist ein <code>ModeSwitchInterface</code> rein ECU-lokal. Es existiert kein Com-Mapping für Mode-Switches über Netzwerk-PDUs. Ein direkter Anschluss eines <code>ModeSwitchInterface</code> über ECU-Grenzen hinweg ist ungültig und schlägt bei der RTE-Generierung fehl.</li>\n<li>Das Proxy-Muster (<code>VehicleClampProxy</code>) ist das normative Entwurfsmuster, um Modus-Anforderungen netzwerkweit zu transportieren.</li>\n<li><strong>RTE-API-Vertrag:</strong></li>\n<li><code>VCC</code> $\\rightarrow$ <code>VCP</code>: Asynchrones oder unblocking Sender/Receiver-API (<code>Rte_Write_&lt;p&gt;_&lt;o&gt;()</code> / <code>Rte_Read_&lt;p&gt;_&lt;o&gt;()</code>).</li>\n<li><code>VCP</code> $\\rightarrow$ <code>BswM</code>: Zugriff auf den BswM-Mode-Request-Port via RTE-Write oder standardisierte BswM-Service-APIs.</li>\n<li><code>BswM</code> $\\rightarrow$ <code>App</code>: BswM nutzt <code>Rte_Switch()</code>. Applikationen greifen über <code>Rte_Mode()</code> ab oder reagieren event-gesteuert auf <code>ModeSwitchEvent</code>.</li>\n<li><strong>BswM-Konfigurationsanforderungen:</strong></li>\n<li>Jedes Steuergerät benötigt im BswM-Modell einen <code>BswMModeRequestPort</code> vom Typ <code>BswMSwComponentType</code>, der auf den Zielport des <code>VCP</code> verweist.</li>\n<li>In der BswM-Konfiguration muss ein <code>BswMActionListItem</code> mit einer <code>BswMAction</code> vom Typ <code>BswMModeSwitch</code> definiert sein, um den RTE-Modus-Switch zu initiieren.</li>\n<li><strong>Timing & Latenzen:</strong></li>\n<li>Die Klemmenreaktion erfolgt asynchron zwischen den ECUs: ECU2 reagiert aufgrund von Bus-Übertragungs- und Debounce-Zeiten verzögert gegenüber ECU1.</li>\n<li>Timeout- und Ausfallüberwachung (z. B. Verlust der Klemmen-PDU via Com-Deadline-Monitoring) muss im BswM von ECU2 konfiguriert werden, um ein sicheres Rückfallverhalten (<em>Safe State</em>) zu gewährleisten.</li>\n</ul>"}], "trans": [{"from": "FIG-61aba51b948a5bba", "to": "FIG-b057440554f96dee", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b057440554f96dee", "to": "FIG-3d60268f1dd13148", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-3d60268f1dd13148", "to": "FIG-b4d9427754c19270", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b4d9427754c19270", "to": "FIG-5c8ede4876b2a0a8", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
